INSERT INTO `exercises` VALUES (1,'Бег на беговой дорожке','квадрицепсы, ягодичные, икры, бицепс бедра','cardio','Встаньте на дорожку, пристегните страховочный трос. Начните с быстрой ходьбы 5 минут для разминки. Затем плавно увеличивайте скорость до легкого бега. Следите за пульсом: 120-150 ударов в минуту. Бегите, приземляясь на среднюю или переднюю часть стопы, не на пятку. Не держитесь за поручни.','гонартроз, коксартроз, плоскостопие 3, сердечная недостаточность',7.50,9.20,'/uploads/exercises/exercise_1.jpg'),(2,'Бурпи','все тело','cardio','Исходное положение — стоя, ноги на ширине плеч. 1) Присядьте, положив ладони на пол. 2) Прыжком отбросьте ноги назад в упор лежа. 3) Сделайте отжимание. 4) Прыжком подтяните ноги к рукам. 5) Выпрыгните вверх с хлопком. Начинайте с 5-10 повторений.','гипертония 2+, тахиаритмии, нестабильная стенокардия',8.00,9.80,'/uploads/exercises/exercise_2.jpg'),(3,'Велотренажер','квадрицепсы, бицепс бедра, ягодичные','cardio','Отрегулируйте высоту седла. Спина прямая. Крутите педали с каденсом 70-90 оборотов в минуту. Колени смотрят вперед.','простатит, геморрой, аневризма бедренной артерии',6.00,7.40,'/uploads/exercises/exercise_3.jpg'),(4,'Прыжки на скакалке','икры, стопа, ягодицы, кор','cardio','Вращайте скакалку кистями. Прыгайте на носках, мягко приземляясь. Прыжок низкий — 2-3 см от пола.','гонартроз, менископатия, плоскостопие, опущение тазовых органов',6.00,7.40,'/uploads/exercises/exercise_4.jpg'),(5,'Ходьба в гору','ягодичные, бицепс бедра, икры','cardio','Установите беговую дорожку с наклоном 10-15%. Скорость — быстрая ходьба 5-7 км/ч. Не держитесь за поручни.','ахиллодиния, плантарный фасциит, тромбоз глубоких вен',5.50,6.80,'/uploads/exercises/exercise_5.jpg'),(6,'Эллиптический тренажер','ноги, ягодицы, кор, руки','cardio','Встаньте на педали. Ноги движутся по эллипсу, противоположная рука тянет ручку на себя. Не отрывайте пятки.','артроз колена 1-2 ст., нестабильность надколенника',5.50,6.80,'/uploads/exercises/exercise_6.jpg'),(7,'Гребной тренажер','спина, ноги, бицепс, дельты, пресс','cardio','Фазы движения: толчок ногами, отклонение корпуса назад, тяга рукояти к груди. Движение плавное.','грыжи поясничные, плечевая нестабильность, перелом лопатки',6.50,8.00,'/uploads/exercises/exercise_7.jpg'),(8,'Степпер','ягодицы, квадрицепсы, икры','cardio','Имитация подъема по лестнице. Давление всей стопой, акцент на пятку для ягодиц.','коксартроз 2-3, ТБС дисплазия, перелом шейки бедра',5.00,6.20,'/uploads/exercises/exercise_8.jpg'),(9,'Махи гирей','спина, ноги, плечи, кор','cardio','Движение идет от бедер, а не от рук. Гиря летит по дуге до уровня плеч.','грыжи поясничные, протрузии, боль в пояснице',6.00,7.40,'/uploads/exercises/exercise_9.jpg'),(10,'Бег на улице','ягодицы, квадрицепсы, икры, бицепс бедра','cardio','Бег на свежем воздухе. Начните с разминки. Следите за пульсом и дыханием.','гонартроз, коксартроз, сердечная недостаточность',7.50,9.20,'/uploads/exercises/exercise_10.jpg'),(11,'Интервальный бег','все мышцы ног, сердечно-сосудистая система','cardio','Чередование спринта (30 сек) и легкого бега/ходьбы (1 мин). Повторять 10-15 раз.','гипертония, тахиаритмии, проблемы с сосудами',8.50,10.50,'/uploads/exercises/exercise_11.jpg'),(12,'Велосипед на улице','квадрицепсы, ягодицы, бицепс бедра','cardio','Езда на велосипеде. Держите спину ровно.','простатит, геморрой, артроз коленей',6.00,7.40,'/uploads/exercises/exercise_12.jpg'),(13,'Плавание вольным стилем','плечи, спина, грудь, ноги','cardio','Плавание кролем на груди. Минимальная нагрузка на суставы.','плечевой артрит, травмы плеча, кожные заболевания',7.00,8.60,'/uploads/exercises/exercise_13.jpg'),(14,'Плавание брассом','грудь, бедра, ягодицы, плечи','cardio','Меньше нагрузки на плечи, чем кроль. Подходит для начинающих.','коленные травмы, проблемы с тазобедренными суставами',6.50,8.00,'/uploads/exercises/exercise_14.jpg'),(15,'Аквааэробика','все тело','cardio','Занятия в воде. Минимальная нагрузка на суставы.','кожные заболевания, инфекции, эпилепсия',5.00,6.20,'/uploads/exercises/exercise_15.jpg'),(16,'Сайклинг','квадрицепсы, ягодицы, бицепс бедра','cardio','Интенсивная групповая велотренировка. Чередование спринтов и подъемов.','проблемы с коленями, варикоз, геморрой',7.50,9.20,'/uploads/exercises/exercise_16.jpg'),(17,'Зумба','все тело','cardio','Латиноамериканские танцы в интенсивном темпе.','проблемы с суставами, беременность (после разрешения врача)',6.00,7.40,'/uploads/exercises/exercise_17.jpg'),(18,'Ходьба с палками','спина, руки, ноги, кор','cardio','Скандинавская ходьба. Включает 90% мышц тела. Меньше нагрузки на колени.','плечевые травмы, проблемы с запястьями',5.00,6.20,'/uploads/exercises/exercise_18.jpg'),(19,'Быстрая ходьба','ноги, ягодицы, кор','cardio','Интенсивная ходьба со скоростью 6-7 км/ч. Подходит для начинающих.','плантарный фасциит, проблемы с коленями',4.50,5.50,'/uploads/exercises/exercise_19.jpg'),(20,'Ходьба по лестнице','ягодицы, квадрицепсы, икры','cardio','Ходьба вверх по лестнице. Отлично для ягодиц и жиросжигания.','проблемы с коленями, коксартроз',7.00,8.60,'/uploads/exercises/exercise_20.jpg'),(21,'Бег в гору','ягодицы, бицепс бедра, квадрицепсы','cardio','Бег вверх по склону. Повышенная нагрузка на ягодицы.','проблемы с коленями, сердечная недостаточность',8.00,9.80,'/uploads/exercises/exercise_21.jpg'),(22,'Кроссфит','все тело','cardio','Интенсивная функциональная тренировка. Чередование прыжков, бурпи, скакалки.','сердечно-сосудистые заболевания, гипертония',8.00,9.80,'/uploads/exercises/exercise_22.jpg'),(23,'Боксирование','плечи, руки, кор, ноги','cardio','Удары по боксерскому мешку. Отличная кардио и разгрузка.','проблемы с плечами, локтями, кистями',7.00,8.60,'/uploads/exercises/exercise_23.jpg'),(24,'Футбол','все мышцы ног, кор','cardio','Игра в футбол. Постоянное движение, спринты, смена направления.','травмы коленей, мениски, проблемы с сосудами',7.50,9.20,'/uploads/exercises/exercise_24.jpg'),(25,'Баскетбол','все мышцы ног, руки, плечи','cardio','Прыжки, спринты, быстрые смены направления.','травмы коленей, голеностопа, проблемы с ахиллом',7.00,8.60,'/uploads/exercises/exercise_25.jpg'),(26,'Волейбол','ноги, плечи, руки','cardio','Прыжки, резкие движения, удары по мячу.','травмы коленей, плеч, пальцев',6.00,7.40,'/uploads/exercises/exercise_26.jpg'),(27,'Жим штанги лежа','большая грудная, трицепс, передняя дельта','strength','Лягте на горизонтальную скамью. Ступни на полу. Лопатки сведены. Хват чуть шире плеч. Опустите штангу к нижней части груди. Выжмите вверх.','плечевой артрит, разрыв ротаторной манжеты, перелом ключицы',4.50,5.50,'/uploads/exercises/exercise_27.jpg'),(28,'Жим гантелей лежа','большая грудная, трицепс, передняя дельта','strength','Лягте на скамью. Опустите гантели в стороны и вниз. Выжмите вверх, сводя вместе.','плече-лопаточный периартрит, разрыв грудной мышцы',4.50,5.50,'/uploads/exercises/exercise_28.jpg'),(29,'Отжимания от пола','грудь, трицепс, передняя дельта','strength','Упор лежа. Тело — прямая линия. Опуститесь, сгибая локти под 45°, выжмите вверх.','боли в запястьях, эпикондилит, перелом лучевой кости',4.50,5.50,'/uploads/exercises/exercise_29.jpg'),(30,'Разведение гантелей лежа','большая грудная','strength','Руки слегка согнуты. Разведите руки в стороны. Верните по дуге.','импинджмент-синдром плеча, разрыв сухожилия бицепса',4.00,4.90,'/uploads/exercises/exercise_30.jpg'),(31,'Кроссовер на грудь','грудь','strength','Встаньте между блоками. Шаг вперед. Сведите руки перед собой.','плечевой тендинит, импинджмент',4.00,4.90,'/uploads/exercises/exercise_31.jpg'),(32,'Жим гантелей на наклонной','грудь, плечи','strength','Лягте на наклонную скамью (30-45°). Гантели на уровне груди. Выжмите вверх.','плечевой артрит, травма вращательной манжеты',4.50,5.50,'/uploads/exercises/exercise_32.jpg'),(33,'Подтягивания широким хватом','широчайшие, большая круглая, трапеция','strength','Вис на перекладине, хват шире плеч. Подтянитесь, сводя лопатки.','грыжи шейного отдела, невралгия затылочного нерва',5.00,6.20,'/uploads/exercises/exercise_33.jpg'),(34,'Тяга штанги в наклоне','широчайшие, трапеция, ромбовидные, бицепс','strength','Наклон корпуса 45°. Штангу тяните к низу живота. Локти назад.','протрузии поясницы, остеохондроз грудной, спондилолистез',4.50,5.50,'/uploads/exercises/exercise_34.jpg'),(35,'Тяга верхнего блока к груди','широчайшие, бицепс, трапеция','strength','Сидя, ноги под валиками. Тяните рукоять к груди. Локти вниз и назад.','плечевой полиартрит, перелом акромиона',4.50,5.50,'/uploads/exercises/exercise_35.jpg'),(36,'Гиперэкстензия','разгибатели спины, ягодичные','strength','Лежа на тренажере лицом вниз. Опуститесь вниз, поднимитесь вверх. Спина прямая.','компрессионный перелом, нестабильность позвоночника',3.50,4.30,'/uploads/exercises/exercise_36.jpg'),(37,'Тяга Т-грифа','широчайшие, ромбовидные, трапеция','strength','Наклон корпуса до параллели. Тяните гриф к груди.','межреберная невралгия, перелом ребер',4.50,5.50,'/uploads/exercises/exercise_37.jpg'),(38,'Шраги с гантелями','верх трапеции, леваторы лопатки','strength','Поднимите плечи вверх. Задержитесь, опустите.','остеохондроз шейный, синдром позвоночной артерии',3.50,4.30,'/uploads/exercises/exercise_38.jpg'),(39,'Тяга гантели в наклоне','широчайшие, бицепс','strength','Упор одной рукой и коленом в скамью. Тяните гантель к поясу.','грыжи поясничные, протрузии',4.00,4.90,'/uploads/exercises/exercise_39.jpg'),(40,'Приседания со штангой','квадрицепсы, ягодичные, приводящие','strength','Штанга на трапеции. Приседайте до параллели бедер. Вес на пятках.','менископатия, гонартроз, сердечная недостаточность',5.00,6.20,'/uploads/exercises/exercise_40.jpg'),(41,'Жим ногами','квадрицепсы, ягодичные, бицепс бедра','strength','Сидя в тренажере. Опустите платформу. Выжмите вверх.','паховая грыжа, протрузия, тромбоз глубоких вен',5.00,6.20,'/uploads/exercises/exercise_41.jpg'),(42,'Выпады со штангой','ягодичные, квадрицепсы, приводящие','strength','Шаг вперед. Опуститесь, пока заднее колено не коснется пола. Вернитесь.','нестабильность колена, мениск, перелом шейки бедра',5.00,6.20,'/uploads/exercises/exercise_42.jpg'),(43,'Румынская тяга','бицепс бедра, ягодичные, разгибатели спины','strength','Штанга в опущенных руках. Наклон вперед, штанга скользит по ногам.','грыжа поясничная, ишиас',4.50,5.50,'/uploads/exercises/exercise_43.jpg'),(44,'Ягодичный мостик со штангой','ягодичные, бицепс бедра','strength','Лежа на спине, ноги согнуты. Штанга на тазу. Поднимите таз вверх.','коксартроз, перелом крестца',4.00,4.90,'/uploads/exercises/exercise_44.jpg'),(45,'Сгибание ног лежа','бицепс бедра','strength','Лежа на животе. Валик на пятках. Согните ноги, подтягивая валик к ягодицам.','киста Бейкера, тромбофлебит подколенной вены',3.50,4.30,'/uploads/exercises/exercise_45.jpg'),(46,'Разгибание ног сидя','квадрицепсы','strength','Сидя в тренажере. Валик над стопами. Выпрямите ноги.','артрит колена, разрыв связки надколенника',3.50,4.30,'/uploads/exercises/exercise_46.jpg'),(47,'Фронтальные приседания','квадрицепсы, ягодичные, кор','strength','Штанга на передних дельтах. Локти вверх. Приседайте вертикально вниз.','проблемы с запястьями, синдром запястного канала',5.00,6.20,'/uploads/exercises/exercise_47.jpg'),(48,'Жим штанги стоя','все пучки дельт, трицепс, трапеция','strength','Штанга на ключицах. Выжмите над головой. Опустите.','остеохондроз шейный, нестабильность плеча',5.00,6.20,'/uploads/exercises/exercise_48.jpg'),(49,'Жим гантелей сидя','передний и средний пучки дельт','strength','Сидя, спина прижата. Гантели на уровне плеч. Выжмите вверх.','акромиально-ключичный артроз, перелом ключицы',4.50,5.50,'/uploads/exercises/exercise_49.jpg'),(50,'Разведение гантелей в стороны','средний пучок дельт','strength','Гантели опущены. Поднимите через стороны до уровня плеч.','тендинит надостной мышцы, импинджмент',4.00,4.90,'/uploads/exercises/exercise_50.jpg'),(51,'Подъем штанги на бицепс стоя','бицепс, плечевая мышца','strength','Хват снизу. Локти прижаты. Поднимите штангу к груди.','эпикондилит медиальный, разрыв бицепса',4.00,4.90,'/uploads/exercises/exercise_51.jpg'),(52,'Молотковые сгибания','бицепс, плечелучевая','strength','Нейтральный хват. Гантели к плечам, кисти не разворачивай.','лучезапястный туннельный синдром, болезнь де Кервена',4.00,4.90,'/uploads/exercises/exercise_52.jpg'),(53,'Подъем гантелей на наклонной','бицепс','strength','Сидя на наклонной скамье. Гантели поднимите к плечам с супинацией.','шейная грыжа, невралгия нерва',4.00,4.90,'/uploads/exercises/exercise_53.jpg'),(54,'Французский жим лежа','трицепс','strength','Лежа на скамье. Штанга над грудью. Опустите ко лбу. Разогните.','артроз локтя, ушиб локтевого нерва, перелом локтевого отростка',4.00,4.90,'/uploads/exercises/exercise_54.jpg'),(55,'Разгибание рук с гантелью из-за головы','трицепс','strength','Сидя, гантель над головой. Опустите за голову. Разогните.','остеофиты локтя, эпикондилит латеральный',4.00,4.90,'/uploads/exercises/exercise_55.jpg'),(56,'Отжимания на брусьях','трицепс, низ груди','strength','Упор на брусьях. Опуститесь до 90° в локтях. Вытолкните себя вверх.','акромиально-ключичное сочленение, нестабильность плеча',5.00,6.20,'/uploads/exercises/exercise_56.jpg'),(57,'Скручивания','прямая мышца живота','strength','Лежа на спине, ноги согнуты. Оторвите лопатки от пола.','грыжа белой линии живота, диастаз прямых',3.50,4.30,'/uploads/exercises/exercise_57.jpg'),(58,'Планка','вся кор (пресс, спина, ягодицы)','strength','Упор на предплечьях. Тело прямая линия. Напрягите пресс и ягодицы.','грыжа пищеводного отверстия, аневризма брюшной аорты',2.50,3.10,'/uploads/exercises/exercise_58.jpg'),(59,'Боковая планка','косая мышца живота','strength','Упор на предплечье сбоку. Тело прямая линия.','реберно-позвоночный артроз, перелом ребра',2.50,3.10,'/uploads/exercises/exercise_59.jpg'),(60,'Обратные скручивания','низ пресса','strength','Лежа на спине. Подтяните колени к груди, отрывая таз.','геморрой, цистит, выпадение прямой кишки',3.50,4.30,'/uploads/exercises/exercise_60.jpg'),(61,'Подъем ног в висе','низ пресса, подвздошно-поясничная','strength','Вис на перекладине. Поднимите прямые ноги до параллели с полом.','грыжа поясничная, спондилолистез',4.00,4.90,'/uploads/exercises/exercise_61.jpg'),(62,'Русский твист','косые мышцы живота','strength','Сидя на ягодицах, ноги согнуты. Поворачивайте корпус вправо и влево.','остеохондроз грудной, грыжа Шморля',3.50,4.30,'/uploads/exercises/exercise_62.jpg'),(63,'Вакуум живота','поперечная мышца живота','strength','Лежа на спине. Выдохните весь воздух. Втяните живот внутрь.','беременность, язва желудка, диафрагмальная грыжа',2.00,2.50,'/uploads/exercises/exercise_63.jpg'),(64,'Приседания','ноги','strength','Приседания с собственным весом. Спина прямая, колени не выходят за носки.',NULL,3.00,3.70,'/uploads/exercises/exercise_64.jpg'),(65,'Становая тяга','спина, ноги, ягодицы, кор','strength','Тяга штанги с пола. Спина прямая на протяжении всего движения.',NULL,4.00,4.90,'/uploads/exercises/exercise_65.jpg'),(66,'Становая тяга на прямых ногах','бицепс бедра, ягодицы, разгибатели спины','strength','Ноги на ширине плеч, колени слегка согнуты. Наклоняйтесь, отводя таз назад.','грыжи поясничные, протрузии',5.00,6.20,'/uploads/exercises/exercise_66.jpg'),(67,'Болгарские сплит-приседания','квадрицепсы, ягодицы, бицепс бедра','strength','Одну ногу поставьте на скамью позади себя. Приседайте.','проблемы с коленями, нестабильность',4.50,5.50,'/uploads/exercises/exercise_67.jpg'),(68,'Отжимания на трицепс','трицепс, грудь','strength','Ладони вместе (ромбовидная форма). Опуститесь грудью к рукам.','проблемы с запястьями, локтями',4.00,4.90,'/uploads/exercises/exercise_68.jpg'),(69,'Наклон к прямым ногам сидя','бицепс бедра, разгибатели спины, икры','stretching','Сидя, ноги прямые. Наклонитесь грудью вперед, сохраняя спину прямой. Задержитесь 20-30 сек.','грыжа L5-S1, перелом позвоночника',2.50,3.10,NULL),(70,'Растяжка четырехглавой лежа на боку','квадрицепс','stretching','Лежа на боку. Согните верхнюю ногу. Тяните пятку к ягодице.','разрыв связки надколенника, инфекционный артрит',2.50,3.10,NULL),(71,'Собака мордой вниз','бицепс бедра, икры, спина','stretching','Из упора на четвереньках поднимите таз вверх. Пятки тяните к полу.','синдром запястного канала, глаукома',2.50,3.10,NULL),(72,'Растяжка груди в дверном проеме','большая и малая грудные','stretching','Встаньте в проем. Упритесь предплечьем в косяк. Поверните корпус.','острый плечевой тендинит, разрыв вращательной манжеты',2.50,3.10,NULL),(73,'Растяжка трицепса','трицепс, широчайшие','stretching','Руку за голову. Другой рукой тяните локоть к голове.','локтевой артроз, перелом плечевой кости',2.50,3.10,NULL),(74,'Бабочка сидя','приводящие бедра, пах','stretching','Сидя, стопы вместе. Колени в стороны. Наклонитесь грудью вперед.','симфизит, тендинопатии, перелом лобковой кости',2.50,3.10,NULL),(75,'Растяжка ягодиц сидя','грушевидная, ягодичные','stretching','Сидя, положите лодыжку на колено. Наклонитесь вперед.','синдром грушевидной мышцы (острая), перелом крестца',2.50,3.10,NULL),(76,'Растяжка шеи латеральная','леваторы лопатки, трапеция','stretching','Наклоните голову в сторону. Противоположную руку вытяните вниз.','шейный остеохондроз, стеноз позвоночного канала',2.00,2.50,NULL),(77,'Растяжка общая','гибкость','stretching','Общая растяжка всего тела после тренировки. Держите каждое положение 15-30 секунд.',NULL,2.50,3.10,NULL);
