--
-- Table structure for table `meal_plan_recipes`
--

DROP TABLE IF EXISTS `meal_plan_recipes`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!40101 SET character_set_client = utf8 */;
CREATE TABLE `meal_plan_recipes` (
  `id` int(11) NOT NULL AUTO_INCREMENT,
  `mplan_id` int(11) NOT NULL,
  `recipe_id` int(11) NOT NULL,
  `meal_type` enum('Завтрак','Перекус','Обед','Полдник','Ужин','Перекус 2') COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `is_completed` tinyint(1) DEFAULT '0',
  `servings` decimal(5,2) NOT NULL DEFAULT '1.00',
  PRIMARY KEY (`id`),
  KEY `mplan_id` (`mplan_id`),
  KEY `recipe_id` (`recipe_id`),
  CONSTRAINT `meal_plan_recipes_ibfk_1` FOREIGN KEY (`mplan_id`) REFERENCES `meal_plan` (`mplan_id`) ON DELETE CASCADE,
  CONSTRAINT `meal_plan_recipes_ibfk_2` FOREIGN KEY (`recipe_id`) REFERENCES `recipes` (`recipe_id`) ON DELETE CASCADE
) ENGINE=InnoDB AUTO_INCREMENT=12287 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
/*!40101 SET character_set_client = @saved_cs_client */;

