/*!40000 ALTER TABLE `recipes` DISABLE KEYS */;
INSERT INTO `recipes` VALUES (1,'Протеиновый блин',210,32,7,6,'weight_loss','яйца, яичные белки, протеин, вода','Ингредиенты: яйцо 1 шт, яичные белки 3 шт, протеин ваниль 20 г, вода 50 мл. Приготовление: Все ингредиенты взбить блендером до однородности. Вылить на разогретую антипригарную сковороду. Жарить 3-4 минуты с каждой стороны до золотистого цвета.','/uploads/recipes/recipe_1.jpg'),(2,'Творожная запеканка с протеином',340,44,9,20,'weight_loss','творог, яйца, протеин, разрыхлитель, ванилин','Ингредиенты: творог 5% 200 г, яйцо 2 шт, протеин 30 г, разрыхлитель 5 г, ванилин. Приготовление: Творог размять вилкой, добавить яйца, протеин, ванилин и разрыхлитель. Тщательно перемешать. Выложить в силиконовую форму. Выпекать при 180°С 25-30 минут.','/uploads/recipes/recipe_2.jpg'),(3,'Куриная грудка с брокколи на пару',380,52,8,12,'weight_loss','куриное филе, брокколи, лимонный сок, специи','Ингредиенты: куриное филе 200 г, брокколи 150 г, лимонный сок 10 мл, специи. Приготовление: Курицу нарезать кубиками, сбрызнуть лимоном, посыпать специями. Брокколи разобрать на соцветия. Готовить в пароварке 20 минут или на пару в кастрюле.','/uploads/recipes/recipe_3.jpg'),(4,'Тунец с творогом и огурцом',310,42,12,8,'weight_loss','тунец, творог, огурец, укроп','Ингредиенты: тунец в собственном соку 120 г, творог 5% 100 г, огурец 150 г, укроп. Приготовление: Тунец размять вилкой, смешать с творогом. Огурец нарезать мелкими кубиками. Добавить рубленый укроп. Всё перемешать. Можно есть как салат или намазывать на хлебцы.','/uploads/recipes/recipe_4.jpg'),(5,'Омлет с курицей и шпинатом',350,45,15,7,'weight_loss','яйца, куриное филе, шпинат, молоко','Ингредиенты: яйца 3 шт, куриное филе отварное 120 г, шпинат 80 г, молоко 1% 50 мл. Приготовление: Яйца взбить с молоком. Курицу нарезать мелко. Шпинат порубить. Смешать всё, жарить на антипригарной сковороде под крышкой 7-10 минут.','/uploads/recipes/recipe_5.jpg'),(6,'Салат с кальмарами и яйцом',290,38,9,12,'weight_loss','кальмары, яйца, огурец, йогурт греческий, зелень','Ингредиенты: кальмары 150 г, яйца 2 шт, огурец 100 г, йогурт греческий 50 г, зелень. Приготовление: Кальмары очистить, отварить в кипящей воде 2-3 минуты, нарезать соломкой. Яйца сварить вкрутую, нарезать. Огурец натереть. Заправить греческим йогуртом.','/uploads/recipes/recipe_6.jpg'),(7,'Рыбные котлеты на пару',320,40,14,6,'weight_loss','филе минтая, яйца, овсяные отруби, лук','Ингредиенты: филе минтая 250 г, яйцо 1 шт, овсяные отруби 20 г, лук 50 г. Приготовление: Рыбу и лук пропустить через мясорубку. Добавить яйцо и отруби. Сформировать котлеты. Готовить на пару 20 минут.','/uploads/recipes/recipe_7.jpg'),(8,'Греческий йогурт с протеином и ягодами',260,35,5,22,'weight_loss','йогурт греческий, протеин, ягоды','Ингредиенты: йогурт греческий 200 г, протеин 20 г, ягоды замороженные 100 г. Приготовление: Йогурт смешать с протеином до однородности. Ягоды разморозить или использовать свежие. Выложить слоями или просто перемешать.','/uploads/recipes/recipe_8.jpg'),(9,'Куриная печень с луком в сметане',370,41,18,11,'weight_loss','куриная печень, лук, сметана, масло','Ингредиенты: куриная печень 200 г, лук 100 г, сметана 10% 50 г, масло для жарки. Приготовление: Печень промыть, нарезать. Лук нашинковать. Обжарить лук, добавить печень, жарить 5-7 минут. Добавить сметану, тушить 5 минут.','/uploads/recipes/recipe_9.jpg'),(10,'Белковый салат с тунцом и фасолью',340,38,12,24,'weight_loss','тунец, фасоль консервированная, яйца, лук зеленый, йогурт','Ингредиенты: тунец 100 г, фасоль консервированная 150 г, яйцо 2 шт, лук зеленый, йогурт 50 г. Приготовление: Тунец размять. Фасоль промыть. Яйца сварить, нарезать. Смешать всё, заправить йогуртом.','/uploads/recipes/recipe_10.jpg'),(11,'Индейка с цветной капустой',360,46,11,15,'weight_loss','филе индейки, цветная капуста, чеснок, специи','Ингредиенты: филе индейки 200 г, цветная капуста 200 г, чеснок, специи. Приготовление: Индейку нарезать, обжарить без масла. Капусту разобрать на соцветия, добавить к индейке. Влить 50 мл воды, тушить под крышкой 15 минут.','/uploads/recipes/recipe_11.jpg'),(12,'Белковый коктейль с бананом',280,35,5,28,'weight_loss','протеин, молоко, банан, лёд','Ингредиенты: протеин 30 г, молоко 1% 200 мл, банан 1 шт, лёд. Приготовление: Все ингредиенты поместить в блендер. Взбивать 30-40 секунд до однородной консистенции. Пить сразу после приготовления.','/uploads/recipes/recipe_12.jpg'),(13,'Запеченная треска с лимоном',270,45,8,3,'weight_loss','филе трески, лимон, розмарин, соль, перец','Ингредиенты: филе трески 200 г, лимон 0.5 шт, розмарин, соль, перец. Приготовление: Треску посолить, поперчить. Сбрызнуть лимонным соком. Выложить на фольгу, добавить розмарин. Запекать при 180°С 15-20 минут.','/uploads/recipes/recipe_13.jpg'),(14,'Овощной омлет с творогом в духовке',390,40,18,18,'weight_loss','яйца, творог, помидоры черри, шпинат','Ингредиенти: яйца 4 шт, творог 5% 100 г, помидоры черри 100 г, шпинат 50 г. Приготовление: Яйца взбить с творогом. Помидоры разрезать пополам, шпинат порубить. Смешать всё. Вылить в форму. Запекать при 180°С 20 минут.','/uploads/recipes/recipe_14.jpg'),(15,'Скумбрия на гриле',410,32,30,0,'weight_loss','скумбрия, лимон, специи для рыбы','Ингредиенты: скумбрия свежая 200 г, лимон, специи для рыбы. Приготовление: Скумбрию выпотрошить, промыть. Натереть специями внутри и снаружи. Запечь на гриле или в духовке по 10 минут с каждой стороны.','/uploads/recipes/recipe_15.jpg'),(16,'Кефир с отрубями и протеином',220,30,6,15,'weight_loss','кефир, протеин, овсяные отруби','Ингредиенты: кефир 1% 250 мл, протеин 25 г, овсяные отруби 20 г. Приготовление: В стакан кефира добавить протеин и отруби. Тщательно перемешать венчиком или ложкой. Дать постоять 2-3 минуты для набухания отрубей.','/uploads/recipes/recipe_16.jpg'),(17,'Куриные фрикадельки в томатном соусе',340,44,12,14,'weight_loss','фарш куриный, яйца, томатная паста, лук','Ингредиенты: фарш куриный 200 г, яйцо 1 шт, томатная паста 30 г, лук 50 г. Приготовление: Фарш смешать с яйцом и мелко рубленым луком. Скатать шарики. В сковороде развести томатную пасту с водой, положить фрикадельки. Тушить 20 минут.','/uploads/recipes/recipe_17.jpg'),(18,'Салат с креветками и авокадо',350,35,18,12,'weight_loss','креветки очищенные, авокадо, руккола, лимонный сок','Ингредиенты: креветки очищенные 150 г, авокадо 80 г, руккола 50 г, лимонный сок 10 мл. Приготовление: Креветки отварить 3 минуты. Авокадо нарезать кубиками. Рукколу порвать. Сбрызнуть лимонным соком. Перемешать.','/uploads/recipes/recipe_18.jpg'),(19,'Белковый пудинг из молока и коллагена',190,30,5,8,'weight_loss','молоко, коллаген, желатин, какао','Ингредиенты: молоко 150 мл, коллаген гидролизованный 20 г, желатин 10 г, какао 5 г. Приготовление: Желатин замочить в молоке на 10 минут. Нагреть до растворения, не кипятить. Добавить коллаген и какао, размешать. Разлить по формам, убрать в холодильник на 2 часа.','/uploads/recipes/recipe_19.jpg'),(20,'Запеченные яйца в авокадо',420,26,32,10,'weight_loss','авокадо, яйца, специи, сыр пармезан','Ингредиенты: авокадо 1 шт, яйца 2 шт, специи, сыр пармезан 10 г. Приготовление: Авокадо разрезать пополам, удалить косточку. Вынуть немного мякоти, чтобы углубить лунку. Разбить в каждую половинку по яйцу. Посыпать специями и тертым сыром. Запекать 15 минут при 180°С.','/uploads/recipes/recipe_20.jpg'),(21,'Гейнер-боул с арахисовой пастой',680,28,35,68,'muscle_gain','овсянка, молоко, арахисовая паста, банан, мед','Ингредиенты: овсянка 60 г, молоко 3.2% 200 мл, арахисовая паста 30 г, банан 1 шт, мед 15 г. Приготовление: Сварить овсяную кашу на молоке. Добавить арахисовую пасту и мед, перемешать. Сверху выложить нарезанный банан.','/uploads/recipes/recipe_21.jpg'),(22,'Макароны с сырно-сливочным соусом и фаршем',780,35,38,72,'muscle_gain','паста твердых сортов, фарш свинина+говядина, сливки, пармезан, сливочное масло','Ингредиенты: паста твердых сортов 80 г, фарш свинина+говядина 120 г, сливки 20% 100 мл, пармезан 30 г, сливочное масло 10 г. Приготовление: Отварить пасту. Фарш обжарить до румянца, влить сливки, тушить 3 минуты. Смешать с пастой, добавить масло и тертый сыр.','/uploads/recipes/recipe_22.jpg'),(23,'Сырники из фермерского творога со сметаной',530,29,28,41,'muscle_gain','творог 9%, яйца, мука, сахар, сметана','Ингредиенты: творог 9% 200 г, яйцо 1 шт, мука 40 г, сахар 20 г, сметана 20% 50 г. Приготовление: Смешать творог, яйцо, муку, сахар. Сформировать сырники. Обжарить на сливочном масле с двух сторон до золотистого цвета. Подавать со сметаной.','/uploads/recipes/recipe_23.jpg'),(24,'Картофельное пюре со сливками и котлетой по-киевски',820,38,45,65,'muscle_gain','картофель, сливки, куриная котлета по-киевски, масло','Ингредиенты: картофель 300 г, сливки 20% 80 мл, куриная котлета по-киевски 1 шт, масло 15 г. Приготовление: Картофель отварить, растолочь с горячими сливками и маслом. Котлету обжарить или запечь. Подавать на пюре.','/uploads/recipes/recipe_24.jpg'),(25,'Омлет с беконом и сыром',590,32,45,8,'muscle_gain','яйца, бекон, сыр твердый, сливки','Ингредиенты: яйца 4 шт, бекон 80 г, сыр твердый 50 г, сливки 20% 50 мл. Приготовление: Бекон нарезать и обжарить. Яйца взбить со сливками, залить бекон. Сверху посыпать тертым сыром. Жарить под крышкой 10 минут.','/uploads/recipes/recipe_25.jpg'),(26,'Рис с куриными бедрами карри и кокосовым молоком',720,38,38,58,'muscle_gain','куриные бедра, рис, кокосовое молоко, паста карри','Ингредиенты: куриные бедра 200 г, рис 70 г, кокосовое молоко 100 мл, паста карри 15 г. Приготовление: Курицу обжарить. Добавить пасту карри и кокосовое молоко. Тушить 10 минут. Рис отварить отдельно. Подавать курицу на рисе.','/uploads/recipes/recipe_26.jpg'),(27,'Орехи и сухофрукты',450,12,30,38,'muscle_gain','грецкие орехи, миндаль, курага, финики','Ингредиенты: грецкие орехи 30 г, миндаль 30 г, курага 40 г, финики 40 г. Приготовление: Просто смешать все ингредиенты. Можно предварительно замочить сухофрукты в горячей воде на 5 минут для мягкости.','/uploads/recipes/recipe_27.jpg'),(28,'Говядина с картофелем в горшочке',690,42,28,55,'muscle_gain','говядина, картофель, морковь, сметана, сыр','Ингредиенты: говядина 150 г, картофель 200 г, морковь 80 г, сметана 30 г, сыр 30 г. Приготовление: Мясо нарезать кубиками. Картофель и морковь тоже. Сложить в горшочек слоями. Добавить сметану, посыпать сыром. Запекать 60 минут при 180°С.','/uploads/recipes/recipe_28.jpg'),(29,'Творожная запеканка со сгущенкой',560,28,22,64,'muscle_gain','творог 9%, яйца, сгущенное молоко, манка','Ингредиенты: творог 9% 250 г, яйца 2 шт, сгущенное молоко 80 г, манка 40 г. Приготовление: Смешать творог, яйца, сгущенку и манку. Оставить на 15 минут. Выложить в форму. Выпекать 35 минут при 180°С.','/uploads/recipes/recipe_29.jpg'),(30,'Бутерброд с авокадо, лососем и сливочным сыром',580,26,38,36,'muscle_gain','хлеб тостовый, авокадо, лосось слабосоленый, сыр сливочный','Ингредиенты: хлеб тостовый 2 куска, авокадо 80 г, слабосоленый лосось 70 г, сыр сливочный 40 г. Приготовление: Хлеб подсушить. Намазать сливочным сыром. Сверху выложить нарезанный авокадо и ломтики лосося.','/uploads/recipes/recipe_30.jpg'),(31,'Паста карбонара с беконом и яйцом',750,32,40,68,'muscle_gain','спагетти, бекон, яйца, пармезан, сливки','Ингредиенты: спагетти 90 г, бекон 80 г, яйца 2 шт, пармезан 40 г, сливки 20% 50 мл. Приготовление: Спагетти отварить. Бекон обжарить до хруста. Яйца смешать со сливками и тертым сыром. Смешать с горячими спагетти и беконом (яйцо приготовится от тепла).','/uploads/recipes/recipe_31.jpg'),(32,'Жареная свинина с жареным картофелем',800,44,48,52,'muscle_gain','свинина, картофель, лук, масло растительное','Ингредиенты: свинина 180 г, картофель 250 г, лук 80 г, масло растительное 20 мл. Приготовление: Свинину нарезать кусочками, обжарить. Картофель нарезать брусочками, обжарить отдельно. В конце смешать, добавить жареный лук.','/uploads/recipes/recipe_32.jpg'),(33,'Молочный коктейль с мороженым и бананом',520,12,22,72,'muscle_gain','молоко, мороженое пломбир, банан, сироп шоколадный','Ингредиенты: молоко 3.2% 250 мл, мороженое пломбир 100 г, банан 1 шт, сироп шоколадный 20 г. Приготовление: Все ингредиенти поместить в блендер. Взбивать до однородной пены. Пить через трубочку.','/uploads/recipes/recipe_33.jpg'),(34,'Плов со свининой',740,35,42,58,'muscle_gain','свинина, рис, морковь, лук, масло','Ингредиенты: свинина 150 г, рис 80 г, морковь 100 г, лук 80 г, масло 20 мл. Приготовление: Мясо обжарить. Добавить нарезанные морковь и лук, пассеровать. Всыпать рис, залить водой на 1.5 см выше риса. Тушить до выпаривания воды 25-30 минут.','/uploads/recipes/recipe_34.jpg'),(35,'Сэндвич с курицей, сыром и майонезом',620,34,34,46,'muscle_gain','булка для бургера, куриное филе, сыр, майонез, салат','Ингредиенты: булка для бургера 1 шт, куриное филе жареное 120 г, сыр 40 г, майонез 30 г, салат. Приготовление: Булочку разрезать, поджарить. Нижнюю часть смазать майонезом. Выложить курицу, сыр, лист салата. Накрыть верхней частью.','/uploads/recipes/recipe_35.jpg'),(36,'Оладьи из кабачков со сметаной',490,14,30,42,'muscle_gain','кабачок, яйца, мука, сметана, масло для жарки','Ингредиенты: кабачок 300 г, яйцо 1 шт, мука 60 г, сметана 20% 60 г, масло для жарки 20 мл. Приготовление: Кабачок натереть, отжать лишнюю жидкость. Добавить яйцо и муку. Жарить оладьи на масле с двух сторон. Подавать со сметаной.','/uploads/recipes/recipe_36.jpg'),(37,'Тыквенная каша с рисом на молоке',470,13,16,72,'muscle_gain','тыква, рис, молоко, сливочное масло, сахар','Ингредиенты: тыква 200 г, рис 50 г, молоко 3.2% 300 мл, сливочное масло 15 г, сахар 15 г. Приготовление: Тыкву нарезать кубиками. Рис промыть. Вскипятить молоко, добавить тыкву и рис. Варить 25 минут до мягкости. Добавить масло и сахар.','/uploads/recipes/recipe_37.jpg'),(38,'Блинчики с творогом и сгущенкой',650,28,28,70,'muscle_gain','блины готовые, творог 9%, сгущенное молоко, сметана','Ингредиенты: блины готовые 4 шт, творог 9% 150 г, сгущенное молоко 50 г, сметана 30 г. Приготовление: Творог смешать со сгущенкой. Выложить на каждый блин, свернуть конвертом. Полить сметаной сверху. При желании поджарить на сливочном масле.','/uploads/recipes/recipe_38.jpg'),(39,'Шашлык из свинины с лавашом и соусом',850,46,52,48,'muscle_gain','свинина, лаваш тонкий, соус ткемали, лук, зелень','Ингредиенты: свинина 200 г, лаваш тонкий 100 г, соус ткемали 40 г, лук 80 г, зелень. Приготовление: Свинину замариновать (лук, специи, уксус) на 2 часа. Обжарить или запечь. На лаваш выложить мясо, соус, зелень. Свернуть рулетом.','/uploads/recipes/recipe_39.jpg'),(40,'Рулет из лаваша с курицей и сыром',520,38,22,42,'muscle_gain','лаваш, куриное филе, сыр, йогурт, чеснок, зелень','Ингредиенты: лаваш 1 шт, куриное филе 150 г, сыр 50 г, йогурт 50 г, чеснок, зелень. Приготовление: Курицу обжарить и нарезать. Смешать йогурт с чесноком. Лаваш смазать соусом, выложить курицу и сыр, свернуть рулетом. Запечь 10 минут при 180°С.','/uploads/recipes/recipe_40.jpg'),(41,'Творожная запеканка с бананом',450,32,14,52,'muscle_gain','творог 9%, яйца, банан, овсяная мука, разрыхлитель','Ингредиенты: творог 9% 200 г, яйца 2 шт, банан 1 шт, овсяная мука 40 г, разрыхлитель. Приготовление: Творог размять. Банан размять вилкой. Смешать всё, выложить в форму. Выпекать 30 минут при 180°С.','/uploads/recipes/recipe_41.jpg'),(42,'Курица с сыром в духовке',480,52,24,6,'muscle_gain','куриное филе, сыр, сметана, чеснок, специи','Ингредиенты: куриное филе 200 г, сыр 60 г, сметана 50 г, чеснок, специи. Приготовление: Курицу нарезать, посолить, поперчить. Смешать сметану с чесноком. Залить курицу, посыпать сыром. Запекать 25 минут при 180°С.','/uploads/recipes/recipe_42.jpg'),(43,'Гречка с печенью и луком',480,38,18,42,'muscle_gain','куриная печень, гречка, лук, сметана','Ингредиенты: куриная печень 200 г, гречка 80 г, лук 100 г, сметана 50 г. Приготовление: Гречку отварить. Печень обжарить с луком, добавить сметану, тушить 5 минут. Смешать с гречкой.','/uploads/recipes/recipe_43.jpg'),(44,'Рыба под сыром',460,48,24,8,'muscle_gain','филе белой рыбы, сыр, сметана, лимон','Ингредиенты: филе белой рыбы 200 г, сыр 60 г, сметана 50 г, лимон. Приготовление: Рыбу посолить, сбрызнуть лимоном. Смазать сметаной, посыпать сыром. Запекать 20 минут при 180°С.','/uploads/recipes/recipe_44.jpg'),(45,'Макароны с курицей и грибами',620,42,22,62,'muscle_gain','макароны, куриное филе, шампиньоны, сливки, сыр','Ингредиенты: макароны 80 г, куриное филе 150 г, шампиньоны 100 г, сливки 100 мл, сыр 30 г. Приготовление: Макароны отварить. Курицу и грибы обжарить. Влить сливки, добавить сыр. Смешать с макаронами.','/uploads/recipes/recipe_45.jpg'),(46,'Картофель с мясом по-деревенски',680,42,32,56,'muscle_gain','свинина, картофель, лук, чеснок, розмарин','Ингредиенты: свинина 180 г, картофель 200 г, лук 80 г, чеснок, розмарин. Приготовление: Мясо нарезать и обжарить. Картофель нарезать дольками. Всё сложить в форму, добавить специи. Запекать 40 минут при 180°С.','/uploads/recipes/recipe_46.jpg'),(47,'Тунец с макаронами',520,42,18,52,'muscle_gain','тунец в собственном соку, макароны, оливки, помидоры, сыр','Ингредиенты: тунец в собственном соку 150 г, макароны 80 г, оливки 50 г, помидоры 100 г, сыр 30 г. Приготовление: Макароны отварить. Тунец размять. Смешать с макаронами, оливками, помидорами. Посыпать сыром.','/uploads/recipes/recipe_47.jpg'),(48,'Свинина с грибами и сметаной',580,46,32,28,'muscle_gain','свинина, шампиньоны, сметана, лук, чеснок','Ингредиенты: свинина 180 г, шампиньоны 120 г, сметана 100 г, лук 80 г, чеснок. Приготовление: Свинину обжарить. Добавить лук и грибы. Влить сметану, тушить 15 минут.','/uploads/recipes/recipe_48.jpg'),(49,'Запеканка из цветной капусты с сыром',420,28,24,28,'muscle_gain','цветная капуста, яйца, сыр, сливки','Ингредиенты: цветная капуста 300 г, яйца 2 шт, сыр 80 г, сливки 50 мл. Приготовление: Капусту отварить 5 минут. Яйца взбить со сливками и сыром. Залить капусту. Запекать 20 минут при 180°С.','/uploads/recipes/recipe_49.jpg'),(50,'Куриные крылышки запеченные',580,42,38,12,'muscle_gain','куриные крылышки, соевый соус, мед, чеснок, имбирь','Ингредиенты: куриные крылышки 250 г, соевый соус 50 мл, мед 20 г, чеснок, имбирь. Приготовление: Смешать соевый соус, мед, чеснок, имбирь. Замариновать крылышки на 30 минут. Запекать 35 минут при 200°С.','/uploads/recipes/recipe_50.jpg');
